set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

banner "备份与恢复演练"

APP_PORT=$(_existing APP_PORT || echo 3000)

db() {
  docker compose exec -T db psql -U "${POSTGRES_USER:-student}" -d "$1" -c "$2"
}

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "前置检查"
say "这是恢复演练，不是生产恢复：全程只操作本机 Docker 与临时库。"
step "确认 Docker 守护进程在运行"
if ! docker info >/dev/null 2>&1; then
  warn "docker 不可用。请启动 Docker Desktop 或 OrbStack 后重新运行本向导。"
  exit 1
fi
if ! command -v openssl >/dev/null 2>&1; then
  warn "缺少 openssl，无法生成数据库密码。装好后重新运行。"
  exit 1
fi
if [[ ! -f package.json || ! -f docker-compose.yml ]]; then
  warn "请在仓库根目录运行本向导。"
  exit 1
fi
note "docker、openssl、仓库目录检查通过。"
pause

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "准备配置与备份目录"
if [[ -f .env ]]; then
  note "已存在 .env，保留原有配置。"
else
  cp .env.example .env
fi
password=$(openssl rand -base64 32 | tr -d '\n')
write_env POSTGRES_PASSWORD "$password"
mkdir -p backups backups/offsite
note "备份目录：./backups 与 ./backups/offsite"
say "演练产生的数据只在这台机器上；.env 与 backups/ 都不会进仓库。"

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "启动服务并等待健康"
say "首次构建需要几分钟，之后会快很多。"
docker compose up -d --build
say "等待 /healthz 返回 200（最多 3 分钟）……"
healthy=""
for _ in $(seq 1 60); do
  if curl -fsS "http://localhost:${APP_PORT}/healthz" >/dev/null 2>&1; then healthy=1; break; fi
  sleep 3
done
if [[ -z "$healthy" ]]; then
  warn "健康检查超时。先看日志：docker compose logs --tail=50 app"
  exit 1
fi
docker compose ps
note "三个服务应全部 running，app 与 backup 为 healthy。"

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "创建演练用的教务管理员与教师"
ask DRILL_ADMIN_LOGIN "教务管理员登录名（回车用 admin）："
DRILL_ADMIN_LOGIN=${DRILL_ADMIN_LOGIN:-admin}
write_env DRILL_ADMIN_LOGIN "$DRILL_ADMIN_LOGIN"
ask_secret DRILL_ADMIN_PASSWORD "教务管理员密码（至少 8 位，记在 .env 里）："
write_env DRILL_ADMIN_PASSWORD "$DRILL_ADMIN_PASSWORD"
docker compose exec -T app node scripts/create-account.mjs \
  --login "$DRILL_ADMIN_LOGIN" --name "演练教务" --role administrator \
  --password "$DRILL_ADMIN_PASSWORD" --no-force-change

ask DRILL_TEACHER_LOGIN "教师登录名（回车用 teacher1）："
DRILL_TEACHER_LOGIN=${DRILL_TEACHER_LOGIN:-teacher1}
write_env DRILL_TEACHER_LOGIN "$DRILL_TEACHER_LOGIN"
ask_secret DRILL_TEACHER_PASSWORD "教师密码："
write_env DRILL_TEACHER_PASSWORD "$DRILL_TEACHER_PASSWORD"
docker compose exec -T app node scripts/create-account.mjs \
  --login "$DRILL_TEACHER_LOGIN" --name "演练教师" --role teacher \
  --password "$DRILL_TEACHER_PASSWORD" --no-force-change

note "两个账号都用 --no-force-change，省掉演练中改密的干扰；密码已存进 .env。"

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "建学期与学籍（浏览器）"
open_url "http://localhost:${APP_PORT}/login"
step "用刚才的教务管理员账号登录。"
step "左侧进入「学年与学期」。"
step "在「新建学年」里填起始年份（如 2025），提交。"
step "在该学年下新建一个学期（上 或 下）。"
step "展开该学期的「设为当前学期」→ 点「确认切换」。"
open_url "http://localhost:${APP_PORT}/admin/students"
step "在「行政班」里新建一个班，名称填「演练 1 班」。"
ask DRILL_STUDENT_NUMBER "演练学生的学号（如 20250101）："
write_env DRILL_STUDENT_NUMBER "$DRILL_STUDENT_NUMBER"
ask_secret DRILL_STUDENT_PASSWORD "该学生的初始密码："
write_env DRILL_STUDENT_PASSWORD "$DRILL_STUDENT_PASSWORD"
step "在「新建学生」里填入：学号、姓名「演练学生」、行政班选「演练 1 班」、"
step "学籍状态选「在读」、初始密码填上面的值，提交。"
pause "完成后按回车继续"

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "建课程、教学班与成绩并发布（浏览器）"
open_url "http://localhost:${APP_PORT}/admin/courses"
step "「新建课程」：名称「演练课程」，学分填 1，提交。"
open_url "http://localhost:${APP_PORT}/admin/teaching-classes"
step "「开设教学班」：学期选当前学期、课程选「演练课程」、"
step "教师选「演练教师」、显示名填「演练教学班」、整班加入选「演练 1 班」，提交。"
step "进入该教学班详情，点「录入成绩」。"
step "添加两个成绩项：平时（满分 100、权重 40）、期末（满分 100、权重 60）。"
step "给「演练学生」两项各填一个分数（例如 80 与 90）。"
step "展开「发布成绩」→ 点「确认发布」。"
note "发布是整体动作，发布后学生立刻可见，同时锁定。"
pause "完成后按回车继续"

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "立即备份并核对产物"
say "先记录备份前的行数，恢复后要用它对比。"
before_counts=$(docker compose exec -T db psql -U "${POSTGRES_USER:-student}" -d "${POSTGRES_DB:-student}" -tAc "
  select
    (select count(*) from accounts) || ',' ||
    (select count(*) from students) || ',' ||
    (select count(*) from grade_items) || ',' ||
    (select count(*) from grade_overalls) || ',' ||
    (select count(*) from grade_change_logs);")
note "备份前行数（accounts,students,grade_items,grade_overalls,logs）：$before_counts"

docker compose exec -T backup sh /scripts/backup.sh
ls -lh backups | sed 's/^/  /'
last=$(docker compose exec -T backup cat /backups/.last-backup 2>/dev/null || true)
if [[ "$last" != ok* ]]; then
  warn "备份状态异常：$last"
  warn "看日志：docker compose logs --tail=50 backup"
  exit 1
fi
note "备份状态：$last"

# ── Stage 8 ───────────────────────────────────────────────────────────────
stage "演练：恢复到临时数据库并比对"
dump=$(ls -1t backups/student-*.dump 2>/dev/null | head -n1 || true)
if [[ -z "$dump" ]]; then
  warn "没找到 backups/student-*.dump，备份可能没落盘。"
  exit 1
fi
say "使用备份文件：$dump"

docker compose exec -T db psql -U "${POSTGRES_USER:-student}" -d postgres \
  -c 'DROP DATABASE IF EXISTS student_restore_check;'
docker compose exec -T db psql -U "${POSTGRES_USER:-student}" -d postgres \
  -c 'CREATE DATABASE student_restore_check;'
docker compose cp "$dump" db:/tmp/restore.dump
if ! docker compose exec -T db pg_restore -U "${POSTGRES_USER:-student}" \
  -d student_restore_check --no-owner --no-privileges /tmp/restore.dump; then
  warn "pg_restore 退出码非 0，恢复失败。"
  exit 1
fi
note "pg_restore 完成。"

restored_counts=$(docker compose exec -T db psql -U "${POSTGRES_USER:-student}" -d student_restore_check -tAc "
  select
    (select count(*) from accounts) || ',' ||
    (select count(*) from students) || ',' ||
    (select count(*) from grade_items) || ',' ||
    (select count(*) from grade_overalls) || ',' ||
    (select count(*) from grade_change_logs);")
say "备份前行数：$before_counts"
say "恢复后行数：$restored_counts"
if [[ "$before_counts" != "$restored_counts" ]]; then
  warn "行数不一致，恢复不算通过。"
  exit 1
fi

accounts=$(docker compose exec -T db psql -U "${POSTGRES_USER:-student}" -d student_restore_check -tAc \
  "select count(*) from accounts where login_name = '$DRILL_ADMIN_LOGIN';")
if [[ "$accounts" != "1" ]]; then
  warn "恢复后的库里找不到演练管理员账号。"
  exit 1
fi

students=$(docker compose exec -T db psql -U "${POSTGRES_USER:-student}" -d student_restore_check -tAc \
  "select count(*) from students where student_number = '$DRILL_STUDENT_NUMBER';")
if [[ "$students" != "1" ]]; then
  warn "恢复后的库里找不到学号 $DRILL_STUDENT_NUMBER 的学生。"
  exit 1
fi

overalls=$(docker compose exec -T db psql -U "${POSTGRES_USER:-student}" -d student_restore_check -tAc "
  select count(*) from grade_publication_overalls po
  join students s on s.id = po.student_id
  where s.student_number = '$DRILL_STUDENT_NUMBER';")
if [[ "${overalls:-0}" -lt 1 ]]; then
  warn "恢复后的库里找不到该学生的已发布总评，成绩快照可能没备份到。"
  exit 1
fi
note "账号、学生、已发布总评与日志行数全部对得上。"

docker compose exec -T db psql -U "${POSTGRES_USER:-student}" -d postgres \
  -c 'DROP DATABASE student_restore_check;'
docker compose exec -T db rm -f /tmp/restore.dump
note "临时库与临时文件已清理。"

# ── Stage 9 ───────────────────────────────────────────────────────────────
stage "回填演练记录"
say "请把下面的内容填进 docs/operations.md 的「5.4 演练记录」表："
note "日期：$(date +%Y-%m-%d)"
note "备份文件：$dump"
note "结果：通过（行数与备份前一致，pg_restore 退出码 0）"
say "填完后把工单 #17 的结论也更新一下，然后提交这次改动。"
pause "填好后按回车结束"

finish
}

run_wizard "$@"; exit
